import json
import re

def parse_skill_md(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    title_match = re.search(r'^#\s+(.+)$', content, re.MULTILINE)
    project_name = title_match.group(1).strip() if title_match else ""

    version_match = re.search(r'\*\*Version:\*\*\s*(.+)', content)
    version = version_match.group(1).strip() if version_match else ""

    license_match = re.search(r'\*\*License:\*\*\s*(.+)', content)
    license_val = license_match.group(1).strip() if license_match else ""

    models = []
    in_models = False
    for line in content.split('\n'):
        if '## Supported Models' in line:
            in_models = True
            continue
        if in_models:
            if line.startswith('##'):
                break
            if line.strip().startswith('-'):
                model = line.strip().lstrip('-').strip()
                if model:
                    models.append(model)

    return {
        "project_name": project_name,
        "version": version,
        "license": license_val,
        "supported_models": models
    }

summary = parse_skill_md('SKILL.md')
with open('output.json', 'w', encoding='utf-8') as f:
    json.dump(summary, f, indent=2)
print("Summary written to output.json")
PYEOF
